// Development-only observations of the WHOLE unchanged pinned def_id.rs.
#![feature(step_trait)]
use def_id_reference::{*,fingerprint::Fingerprint,stable_hash::{StableHash,StableHashCtxt,StableHashControls,StableHasher,RawDefId,RawSpan,ToStableHashKey,StableOrd}};
use rustc_hashes::Hash64;
use serde_json::{Value,json};
use rustc_serialize::{Encoder,Decoder,Encodable,Decodable};
use std::{cell::RefCell,fmt,hash::{Hash,Hasher},io::{self,BufRead},os::unix::ffi::OsStringExt,iter::Step,ops::{Add,AddAssign},panic::{self,AssertUnwindSafe}};
fn number(q:&Value,k:&str)->u64{q[k].as_u64().unwrap_or(0)}fn text<'a>(q:&'a Value,k:&str)->&'a str{q[k].as_str().unwrap_or("")}fn bit(q:&Value,k:&str)->bool{q[k].as_bool().unwrap_or(false)}
fn id(q:&Value)->DefId{DefId{krate:CrateNum::from_u32(number(q,"crate")as u32),index:DefIndex::from_u32(number(q,"index")as u32)}}
fn raw(value:DefId)->[u32;2]{[value.krate.as_u32(),value.index.as_u32()]}
fn payload(p:Box<dyn std::any::Any+Send>)->String{if let Some(s)=p.downcast_ref::<&str>(){s.to_string()}else if let Some(s)=p.downcast_ref::<String>(){s.clone()}else{"opaque panic".into()}}
struct Trace(Vec<String>);impl Hasher for Trace{fn finish(&self)->u64{panic!("unexpected tracer finish")}fn write(&mut self,b:&[u8]){self.0.push(format!("bytes:{}",hex(b)))}fn write_u32(&mut self,n:u32){self.0.push(format!("u32:{n}"))}fn write_u64(&mut self,n:u64){self.0.push(format!("u64:{n}"))}}
fn trace<T:Hash>(value:T)->Vec<String>{let mut h=Trace(Vec::new());value.hash(&mut h);h.0}
fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
struct Ctx{events:RefCell<Vec<String>>}
impl StableHashCtxt for Ctx{
 fn stable_hash_span(&mut self,span:RawSpan,h:&mut StableHasher){self.events.borrow_mut().push(format!("span:{}",span.0));h.write_u64(span.0)}
 fn def_path_hash(&self,id:RawDefId)->Fingerprint{self.events.borrow_mut().push(format!("key:{}:{}",id.0,id.1));Fingerprint::new(Hash64::new(0xa55aa55aa55aa55a^(id.0 as u64)),Hash64::new(0x123456789abc0000+(id.1 as u64)))}
 fn stable_hash_controls(&self)->StableHashControls{self.events.borrow_mut().push("controls".into());StableHashControls{hash_spans:true}}
 fn assert_default_stable_hash_controls(&self,msg:&str){self.events.borrow_mut().push(format!("assert:{msg}"))}
}
fn stable<T:StableHash>(value:T)->Value{let mut ctx=Ctx{events:RefCell::new(Vec::new())};let mut h=StableHasher::new();h.write(b"prefix");value.stable_hash(&mut ctx,&mut h);let fp:Fingerprint=h.finish();let(a,b)=fp.split();json!({"hash":[a.as_u64(),b.as_u64()],"events":ctx.events.into_inner()})}
fn core(q:&Value)->Value{let a=id(q);let local=LocalDefId{local_def_index:a.index};let modu=ModId::new_unchecked(a);let localmod=LocalModId::new_unchecked(local);let fp=DefPathHash(Fingerprint::new(Hash64::new(number(q,"first")),Hash64::new(number(q,"second"))));let stable_id=fp.stable_crate_id();let zero=DefPathHash::default();let mut ctx=Ctx{events:RefCell::new(Vec::new())};let key=a.to_stable_hash_key(&mut ctx);let maybe=a.as_local().map(|v|v.local_def_index.as_u32());let expected=panic::catch_unwind(||a.expect_local()).map(|v|json!(v.local_def_index.as_u32())).unwrap_or_else(|p|json!(payload(p)));let mut unhash=def_id_reference::unhash::Unhasher::default();fp.hash(&mut unhash);
 json!({"raw":raw(a),"roundtrip":raw(DefId::from_raw_def_id(a.to_raw_def_id())),"is_local":a.is_local(),"as_local":maybe,"expect_local":expected,"is_root":a.is_crate_root(),"as_root":a.as_crate_root().map(|n|n.as_u32()),"is_top":a.is_top_level_module(),"crate_def":raw(a.krate.as_def_id()),"crate_mod":raw(a.krate.as_mod_id().to_def_id()),"local_def":raw(local.to_def_id()),"local_top":local.is_top_level_module(),"mod_def":raw(modu.to_def_id()),"mod_local":modu.as_local().map(|v|v.to_local_def_id().local_def_index.as_u32()),"mod_top":modu.is_top_level_module(),"localmod_def":raw(localmod.to_def_id()),"localmod_mod":raw(localmod.to_mod_id().to_def_id()),"hash_id":trace(a),"hash_local":trace(local),"hash_mod":trace(modu),"hash_localmod":trace(localmod),"hash_crate":trace(a.krate),"hash_index":trace(a.index),"hash_path":trace(fp),"hash_stable_id":trace(stable_id),"unhash_path":unhash.finish(),"path_parts":[stable_id.as_u64(),fp.local_hash().as_u64()],"zero_path":[zero.stable_crate_id().as_u64(),zero.local_hash().as_u64()],"stable_id":stable(a),"stable_local":stable(local),"stable_crate":stable(a.krate),"stable_mod":stable(modu),"stable_localmod":stable(localmod),"stable_path":stable(fp),"stable_stable_id":stable(stable_id),"key":[key.stable_crate_id().as_u64(),key.local_hash().as_u64()],"key_events":ctx.events.into_inner(),"clones":[a==a.clone(),local==local.clone(),modu==modu.clone(),localmod==localmod.clone(),fp==fp.clone(),stable_id==stable_id.clone()],"marker":DefPathHash::CAN_USE_UNSTABLE_SORT})
}
fn step<T:Idx+Step+Add<usize,Output=T>+AddAssign<usize>>(q:&Value)->Value{let a=number(q,"a")as usize;let n=number(q,"n")as usize;let kind=text(q,"method");let value=T::new(a);match kind{
 "new"=>json!(value.index()),"between"=>{let(lo,hi)=T::steps_between(&value,&T::new(number(q,"b")as usize));json!([lo,hi])},
 "plus"=>json!(value.plus(n).index()),"increment"=>{let mut value=value;let result=panic::catch_unwind(AssertUnwindSafe(||value.increment_by(n)));json!({"after":value.index(),"panic":result.err().map(payload)})},
 "add"=>json!((value+n).index()),"assign"=>{let mut value=value;let result=panic::catch_unwind(AssertUnwindSafe(||value+=n));json!({"after":value.index(),"panic":result.err().map(payload)})},
 "forward_checked"=>json!(T::forward_checked(value,n).map(Idx::index)),"backward_checked"=>json!(T::backward_checked(value,n).map(Idx::index)),
 "forward_overflowing"=>{let(v,o)=T::forward_overflowing(value,n);json!([v.index(),o])},"backward_overflowing"=>{let(v,o)=T::backward_overflowing(value,n);json!([v.index(),o])},
 "forward"=>json!(T::forward(value,n).index()),"backward"=>json!(T::backward(value,n).index()),_=>panic!("unknown step operation")}}
struct Sink{calls:Vec<String>,accepted:String,fail:i64,chars:bool}
impl Sink{fn record(&mut self,kind:&str,s:&str)->fmt::Result{let n=self.calls.len()as i64;self.calls.push(format!("{kind}:{}",hex(s.as_bytes())));if n==self.fail{Err(fmt::Error)}else{self.accepted.push_str(s);Ok(())}}}
impl fmt::Write for Sink{fn write_str(&mut self,s:&str)->fmt::Result{self.record("S",s)}fn write_char(&mut self,c:char)->fmt::Result{if self.chars{self.record("C",c.encode_utf8(&mut[0;4]))}else{self.write_str(c.encode_utf8(&mut[0;4]))}}}
struct Observed<'a>{value:&'a dyn fmt::Debug,after:&'a RefCell<Value>}
impl fmt::Debug for Observed<'_>{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{let result=self.value.fmt(f);*self.after.borrow_mut()=json!([f.fill()as u32,match f.align(){None=>0,Some(fmt::Alignment::Left)=>1,Some(fmt::Alignment::Right)=>2,Some(fmt::Alignment::Center)=>3}]);result}}
fn render_debug(sink:&mut Sink,value:&dyn fmt::Debug,mode:u64,after:&RefCell<Value>)->fmt::Result{let v=Observed{value,after};match mode{0=>fmt::write(sink,format_args!("{v:?}")),1=>fmt::write(sink,format_args!("{v:#?}")),2=>fmt::write(sink,format_args!("{v:x?}")),3=>fmt::write(sink,format_args!("{v:X?}")),4=>fmt::write(sink,format_args!("{v:#x?}")),5=>fmt::write(sink,format_args!("{v:+08?}")),6=>fmt::write(sink,format_args!("{v:08x?}")),7=>fmt::write(sink,format_args!("{v:*>12?}")),8=>fmt::write(sink,format_args!("{v:*<12?}")),9=>fmt::write(sink,format_args!("{v:*^13?}")),10=>fmt::write(sink,format_args!("{v:.2?}")),11=>fmt::write(sink,format_args!("{v:+#08x?}")),12=>fmt::write(sink,format_args!("{v:-08?}")),13=>fmt::write(sink,format_args!("{v:🦀^12?}")),14=>fmt::write(sink,format_args!("{v:\n>8?}")),15=>fmt::write(sink,format_args!("{v:\0>8?}")),_=>panic!("unknown format")}}
struct CrateDisplay<'a>(&'a CrateNum);impl fmt::Debug for CrateDisplay<'_>{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{fmt::Display::fmt(self.0,f)}}
struct StableHex<'a>(&'a StableCrateId);impl fmt::Debug for StableHex<'_>{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{fmt::LowerHex::fmt(self.0,f)}}
fn format(q:&Value)->Value{let a=id(q);let fp=DefPathHash(Fingerprint::new(Hash64::new(number(q,"first")),Hash64::new(number(q,"second"))));let stable=fp.stable_crate_id();let mut sink=Sink{calls:Vec::new(),accepted:String::new(),fail:q["fail"].as_i64().unwrap_or(-1),chars:bit(q,"chars")};let after=RefCell::new(Value::Null);let local=LocalDefId{local_def_index:a.index};let modu=ModId::new_unchecked(a);let localmod=LocalModId::new_unchecked(local);let controls=StableHashControls{hash_spans:bit(q,"exe")};let display=CrateDisplay(&a.krate);let lower=StableHex(&stable);let v:&dyn fmt::Debug=match text(q,"kind"){"crate"=>&a.krate,"crate_display"=>&display,"stable_hex"=>&lower,"index"=>&a.index,"id"=>&a,"local"=>&local,"mod"=>&modu,"localmod"=>&localmod,"path"=>&fp,"stable"=>&stable,"controls"=>&controls,_=>panic!("unknown format kind")};let result=render_debug(&mut sink,v,number(q,"mode"),&after);json!({"error":result.is_err(),"text":sink.accepted,"calls":sink.calls,"after":after.into_inner()})}
fn new_crate(q:&Value)->Value{if let Some(raw)=q["version_hex"].as_str(){let bytes=raw.as_bytes().chunks(2).map(|b|u8::from_str_radix(std::str::from_utf8(b).unwrap(),16).unwrap()).collect::<Vec<_>>();unsafe{std::env::set_var("RUSTC_FORCE_RUSTC_VERSION",std::ffi::OsString::from_vec(bytes))}}else{unsafe{std::env::remove_var("RUSTC_FORCE_RUSTC_VERSION")}};let name:&'static str=Box::leak(text(q,"name").to_owned().into_boxed_str());let cfg:&'static str=Box::leak(text(q,"cfg").to_owned().into_boxed_str());let metadata=q["metadata"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect();let value=StableCrateId::new(Symbol(name),bit(q,"exe"),metadata,cfg);json!({"id":value.as_u64(),"debug":format!("{value:?}")})}

thread_local!{static CODEC_EVENTS:RefCell<Vec<String>>=const{RefCell::new(Vec::new())};}
fn codec_event(s:String,fail:i64,kind:&str){let n=CODEC_EVENTS.with(|v|{let mut v=v.borrow_mut();let n=v.len()as i64;v.push(s);n});if n==fail{panic!("{kind}")}}
struct CE<const LOCAL:bool>{fail:i64}
macro_rules! emit_codec{($($name:ident:$t:ty),*)=>{$(fn $name(&mut self,v:$t){codec_event(format!("{}:{v}",stringify!($name)),self.fail,"encoder")})*}}
impl<const B:bool>Encoder for CE<B>{emit_codec!(emit_usize:usize,emit_u128:u128,emit_u64:u64,emit_u32:u32,emit_u16:u16,emit_u8:u8,emit_isize:isize,emit_i128:i128,emit_i64:i64,emit_i32:i32,emit_i16:i16);fn emit_raw_bytes(&mut self,b:&[u8]){codec_event(format!("raw:{}",hex(b)),self.fail,"encoder")}}
macro_rules! codec_required{()=>{fn encode_def_id(&mut self,id:DefId){codec_event(format!("def:{}:{}",id.krate.as_u32(),id.index.as_u32()),self.fail,"encoder")}fn encode_def_index(&mut self,id:DefIndex){codec_event(format!("index:{}",id.as_u32()),self.fail,"encoder")}fn encode_crate_num(&mut self,id:CrateNum){codec_event(format!("crate:{}",id.as_u32()),self.fail,"encoder")}}}
impl SpanEncoder for CE<false>{codec_required!();}
impl SpanEncoder for CE<true>{codec_required!();fn encode_local_def_id(&mut self,id:LocalDefId){codec_event(format!("local:{}",id.local_def_index.as_u32()),self.fail,"encoder")}}
fn encode_codec<E:SpanEncoder>(q:&Value,e:&mut E){let id=id(q);let local=LocalDefId{local_def_index:id.index};let path=DefPathHash(Fingerprint::new(Hash64::new(number(q,"first")),Hash64::new(number(q,"second"))));match text(q,"kind"){"id"=>id.encode(e),"index"=>id.index.encode(e),"crate"=>id.krate.encode(e),"local"=>local.encode(e),"mod"=>ModId::new_unchecked(id).encode(e),"localmod"=>LocalModId::new_unchecked(local).encode(e),"path"=>path.encode(e),"stable"=>path.stable_crate_id().encode(e),_=>panic!("unknown codec kind")}}
struct CD{raw:Vec<u8>,id:DefId,fail:i64,pos:usize}
macro_rules! unused_read{($($name:ident:$t:ty),*)=>{$(fn $name(&mut self)->$t{panic!(concat!("unused decoder ",stringify!($name)))})*}}
impl Decoder for CD{unused_read!(read_usize:usize,read_u128:u128,read_u64:u64,read_u32:u32,read_u16:u16,read_u8:u8,read_isize:isize,read_i128:i128,read_i64:i64,read_i32:i32,read_i16:i16);fn read_raw_bytes(&mut self,n:usize)->&[u8]{codec_event(format!("raw-read:{n}"),self.fail,"decoder");self.pos+=self.raw.len();&self.raw}fn peek_byte(&self)->u8{self.raw[self.pos]}fn position(&self)->usize{self.pos}}
impl BlobDecoder for CD{fn decode_local_def_id(&mut self)->LocalDefId{codec_event("decode-local".into(),self.fail,"decoder");LocalDefId{local_def_index:self.id.index}}fn decode_def_index(&mut self)->DefIndex{codec_event("decode-index".into(),self.fail,"decoder");self.id.index}}
impl SpanDecoder for CD{fn decode_def_id(&mut self)->DefId{codec_event("decode-def".into(),self.fail,"decoder");self.id}fn decode_crate_num(&mut self)->CrateNum{codec_event("decode-crate".into(),self.fail,"decoder");self.id.krate}}
fn codec(q:&Value)->Value{CODEC_EVENTS.with(|v|v.borrow_mut().clear());let fail=q["fail"].as_i64().unwrap_or(-1);let result=panic::catch_unwind(AssertUnwindSafe(||{if text(q,"method")=="encode"{if bit(q,"override"){encode_codec(q,&mut CE::<true>{fail})}else{encode_codec(q,&mut CE::<false>{fail})};return Value::Null};let bytes=text(q,"raw_hex").as_bytes().chunks(2).map(|s|u8::from_str_radix(std::str::from_utf8(s).unwrap(),16).unwrap()).collect();let mut d=CD{raw:bytes,id:id(q),fail,pos:0};match text(q,"kind"){"id"=>json!(raw(DefId::decode(&mut d))),"index"=>json!(DefIndex::decode(&mut d).as_u32()),"crate"=>json!(CrateNum::decode(&mut d).as_u32()),"local"=>json!(LocalDefId::decode(&mut d).local_def_index.as_u32()),"mod"=>json!(raw(ModId::decode(&mut d).to_def_id())),"localmod"=>json!(LocalModId::decode(&mut d).to_local_def_id().local_def_index.as_u32()),"path"=>{let p=DefPathHash::decode(&mut d);json!([p.stable_crate_id().as_u64(),p.local_hash().as_u64()])},"stable"=>json!(StableCrateId::decode(&mut d).as_u64()),_=>panic!("unknown codec kind")}}));let(value,error)=match result{Ok(v)=>(v,Value::Null),Err(e)=>(Value::Null,json!(payload(e)))};json!({"value":value,"panic":error,"events":CODEC_EVENTS.with(|v|v.borrow().clone())})}
struct RawHashTrace{events:Vec<String>,fail:i64,calls:i64}
impl RawHashTrace{fn record(&mut self,text:String){self.events.push(text);let call=self.calls;self.calls+=1;if call==self.fail{panic!("hasher")}}}
impl Hasher for RawHashTrace{fn write(&mut self,b:&[u8]){self.record(format!("bytes:{}",hex(b)))}fn finish(&self)->u64{panic!("unexpected finish")}}
struct TypedHashTrace(RawHashTrace);impl Hasher for TypedHashTrace{fn write(&mut self,b:&[u8]){self.0.write(b)}fn finish(&self)->u64{self.0.finish()}fn write_u8(&mut self,v:u8){self.0.record(format!("u8:{v}"))}fn write_u32(&mut self,v:u32){self.0.record(format!("u32:{v}"))}fn write_u64(&mut self,v:u64){self.0.record(format!("u64:{v}"))}}
fn full_hash_input<T:Hash+Copy,H:Hasher>(value:T,q:&Value,h:&mut H){match text(q,"method"){"single"=>value.hash(h),"slice"=>T::hash_slice(&[value,value],h),"empty"=>T::hash_slice(&[],h),_=>panic!("unknown hash input")}}
fn full_hash_value<H:Hasher>(q:&Value,h:&mut H){let value=id(q);let local=LocalDefId{local_def_index:value.index};let path=DefPathHash(Fingerprint::new(number(q,"first"),number(q,"second")));match text(q,"kind"){"crate"=>full_hash_input(value.krate,q,h),"index"=>full_hash_input(value.index,q,h),"id"=>full_hash_input(value,q,h),"local"=>full_hash_input(local,q,h),"mod"=>full_hash_input(ModId::new_unchecked(value),q,h),"localmod"=>full_hash_input(LocalModId::new_unchecked(local),q,h),"path"=>full_hash_input(path,q,h),"stable"=>full_hash_input(path.stable_crate_id(),q,h),"controls"=>full_hash_input(StableHashControls{hash_spans:bit(q,"exe")},q,h),_=>panic!("unknown hash kind")}}
fn full_hash(q:&Value)->Value{let fail=q["fail"].as_i64().unwrap_or(-1);match text(q,"name"){"raw"=>{let mut h=RawHashTrace{events:Vec::new(),fail,calls:0};let error=panic::catch_unwind(AssertUnwindSafe(||full_hash_value(q,&mut h))).err().map(payload);json!({"panic":error,"events":h.events,"calls":h.calls})},"typed"=>{let mut h=TypedHashTrace(RawHashTrace{events:Vec::new(),fail,calls:0});let error=panic::catch_unwind(AssertUnwindSafe(||full_hash_value(q,&mut h))).err().map(payload);json!({"panic":error,"events":h.0.events,"calls":h.0.calls})},"unhash"=>{let mut h=def_id_reference::unhash::Unhasher::default();h.write_u64(number(q,"a"));let error=panic::catch_unwind(AssertUnwindSafe(||full_hash_value(q,&mut h))).err().map(payload);json!({"panic":error,"value":h.finish()})},_=>panic!("unknown full hasher")}}
fn run(q:&Value)->Value{match text(q,"op"){"core"=>core(q),"full_hash"=>full_hash(q),"new_crate"=>new_crate(q),"codec"=>codec(q),"step"=>if text(q,"kind")=="crate"{step::<CrateNum>(q)}else{step::<DefIndex>(q)},"format"=>format(q),_=>panic!("unknown operation")}}
fn main(){panic::set_hook(Box::new(|_|{}));for line in io::stdin().lock().lines(){let q:Value=serde_json::from_str(&line.unwrap()).unwrap();let result=panic::catch_unwind(AssertUnwindSafe(||run(&q))).unwrap_or_else(|p|json!({"panic":payload(p)}));println!("{}",json!({"request":q,"result":result}))}}
